  constructor(defaultName: string, private defaultFormatter: Formatter) {
    this.map.set(defaultName, defaultFormatter);
  }
  register(name: string, fmt: Formatter) { this.map.set(name, fmt); }
  get(name: string): Formatter { return this.map.get(name) || this.defaultFormatter; }
